118	// resolveGateway walks from the root CID through each path segment against a
119	// single consistent snapshot of the object store: the read lock is held for
120	// the whole walk, so concurrent garbage collection can never make one
121	// request observe objects from different points in time. It never initiates
122	// a remote retrieval; locally absent referenced objects fail the request.
123	func (s *store) resolveGateway(rootCID string, segments []string) gatewayOutcome {
124		s.mu.RLock()
125		defer s.mu.RUnlock()
