151				}
152				return gatewayOutcome{obj: target, directory: false}
153			}
154			target := s.objects[entry.cid]
155			if target == nil {
156				return gatewayOutcome{code: "gateway_target_missing", status: http.StatusFailedDependency}
157			}
158			childEntries, valid := parseDirectory(target.body())
159			if !valid {
160				return gatewayOutcome{code: "invalid_directory", status: http.StatusUnprocessableEntity}
161			}
162			if last {
163				return gatewayOutcome{obj: target, directory: true}
