204		if err != nil || version != directoryVersion {
205			return nil, false
206		}
207		raw := *doc.Entries
208		if len(raw) > maxDirectoryEntries {
209			return nil, false
210		}
211		entries := make(map[string]directoryEntry, len(raw))
212		prev := ""
213		for i := range raw {
214			e := raw[i]
215			if e.Name == nil || e.Type == nil || e.CID == nil {
216				return nil, false
217			}
218			name := *e.Name
219			if !validDirectoryName(name) || !runesLess(prev, name) {
220				return nil, false
221			}
222			if *e.Type != "file" && *e.Type != "directory" {
223				return nil, false
224			}
225			if !validCID(*e.CID) {
226				return nil, false
227			}
228			entries[name] = directoryEntry{name: name, typ: *e.Type, cid: *e.CID}
229			prev = name
230		}
231		return entries, true
232	}
233	
234	// validDirectoryName reports whether name satisfies the entry-name contract:
235	// 1..255 Unicode code points, neither "." nor "..", without "/", "\\", NUL
236	// or any Cc control character.
