238		n := utf8.RuneCountInString(name)
239		if n < 1 || n > maxNameRunes || name == "." || name == ".." {
240			return false
241		}
242		if strings.ContainsAny(name, `/\`) {
243			return false
244		}
245		for _, r := range name {
246			if r < 0x20 || r == 0x7f || (r >= 0x80 && r <= 0x9f) {
247				return false
248			}
249		}
250		return true
251	}
