254	// UTF-8 preserves code-point order byte-wise, but the comparison is done on
255	// runes to state the contract directly. Inputs are already valid UTF-8.
256	func runesLess(a, b string) bool {
257		for a != "" && b != "" {
258			ra, sizeA := utf8.DecodeRuneInString(a)
259			rb, sizeB := utf8.DecodeRuneInString(b)
260			if ra != rb {
261				return ra < rb
262			}
