269	// decodeGatewaySegment percent-decodes exactly one raw path segment, exactly
270	// once: every "%" must be followed by two hex digits, "+" is literal and
271	// there is no recursive decoding. The caller is responsible for the UTF-8
272	// and character checks on the result.
273	func decodeGatewaySegment(seg string) (string, bool) {
274		if !strings.ContainsRune(seg, '%') {
275			return seg, true
276		}
277		var b strings.Builder
278		b.Grow(len(seg))
279		for i := 0; i < len(seg); i++ {
280			c := seg[i]
281			if c != '%' {
282				b.WriteByte(c)
283				continue
284			}
285			if i+2 >= len(seg) {
286				return "", false
287			}
288			hi, okHi := hexValue(seg[i+1])
289			lo, okLo := hexValue(seg[i+2])
290			if !okHi || !okLo {
291				return "", false
292			}
293			b.WriteByte(hi<<4 | lo)
294			i += 2
295		}
296		return b.String(), true
297	}
298	
299	// hexValue converts one hexadecimal digit to its value.
300	func hexValue(c byte) (byte, bool) {
301		switch {
302		case c >= '0' && c <= '9':
303			return c - '0', true
304		case c >= 'a' && c <= 'f':
305			return c - 'a' + 10, true
306		case c >= 'A' && c <= 'F':
307			return c - 'A' + 10, true
308		}
309		return 0, false
310	}
