		{http.MethodGet, "/v1/pins/" + strings.Repeat("0", 64), "PUT, DELETE"},
		{http.MethodPost, "/v1/pins/" + strings.Repeat("0", 64), "PUT, DELETE"},
		{http.MethodGet, "/v1/gc", http.MethodPost},
		{http.MethodDelete, "/v1/gc", http.MethodPost},
	}
